  @protected
  void sse_encode_ui_error(UiError self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case UiError_UnknownWorkspace(field0: final field0):
        sse_encode_i_32(0, serializer);
        sse_encode_String(field0, serializer);
      case UiError_Transition(field0: final field0):
        sse_encode_i_32(1, serializer);
        sse_encode_String(field0, serializer);
      case UiError_NoIdentity():
        sse_encode_i_32(2, serializer);
      case UiError_StoreLocked():
        sse_encode_i_32(3, serializer);
      case UiError_Crypto(field0: final field0):
        sse_encode_i_32(4, serializer);
        sse_encode_String(field0, serializer);
      case UiError_Storage(field0: final field0):
        sse_encode_i_32(5, serializer);
        sse_encode_String(field0, serializer);
      case UiError_VaultLocked():
        sse_encode_i_32(6, serializer);
      case UiError_Engine(field0: final field0):
        sse_encode_i_32(7, serializer);
        sse_encode_String(field0, serializer);
    }
  }

